import{_ as i,o as a,c as t,a0 as l}from"./chunks/framework.Bogozrur.js";const c=JSON.parse('{"title":"2026-07-24：搭建 RoboMaster 自瞄仿真环境","description":"","frontmatter":{},"headers":[],"relativePath":"blog/2026-07-24-rm-simulation-setup.md","filePath":"blog/2026-07-24-rm-simulation-setup.md"}'),e={name:"blog/2026-07-24-rm-simulation-setup.md"};function n(h,s,p,k,d,r){return a(),t("div",null,[...s[0]||(s[0]=[l(`<h1 id="_2026-07-24-搭建-robomaster-自瞄仿真环境" tabindex="-1">2026-07-24：搭建 RoboMaster 自瞄仿真环境 <a class="header-anchor" href="#_2026-07-24-搭建-robomaster-自瞄仿真环境" aria-label="Permalink to &quot;2026-07-24：搭建 RoboMaster 自瞄仿真环境&quot;">​</a></h1><p>今天用 AI 辅助，从零搭建了同济 SuperPower 战队 25 赛季自瞄系统的 Windows 仿真环境，并跑通了完整的自瞄开火测试。虽然大部分操作是 AI 执行的，但过程中学到了很多关于项目架构、编译流程和自瞄原理的知识。</p><h2 id="做了什么" tabindex="-1">做了什么 <a class="header-anchor" href="#做了什么" aria-label="Permalink to &quot;做了什么&quot;">​</a></h2><h3 id="环境搭建" tabindex="-1">环境搭建 <a class="header-anchor" href="#环境搭建" aria-label="Permalink to &quot;环境搭建&quot;">​</a></h3><p>整个项目依赖链比较长，涉及多个工具和库：</p><ul><li><strong>Visual Studio 2026 Build Tools</strong>：提供 MSVC 编译器（<code>cl.exe</code>、<code>link.exe</code>）</li><li><strong>vcpkg</strong>：C++ 包管理器，用来安装 OpenCV、fmt、spdlog、Eigen、yaml-cpp</li><li><strong>easywsclient</strong>：轻量 WebSocket 客户端库，桥程序通过它和游戏通信</li><li><strong>OpenVINO</strong>：Intel 的神经网络推理引擎，用来跑 YOLO 检测模型</li></ul><p>这些依赖在 Windows 上手动配确实繁琐，尤其是 vcpkg 编译 OpenCV 要好几分钟。</p><h3 id="编译过程" tabindex="-1">编译过程 <a class="header-anchor" href="#编译过程" aria-label="Permalink to &quot;编译过程&quot;">​</a></h3><p>项目用 CMake 构建，但 Windows 上不能直接 <code>cmake -B build</code>，需要额外指定：</p><ol><li>vcpkg 的 toolchain 文件（让 CMake 知道去哪找库）</li><li>Eigen 的头文件路径（vcpkg 装的 Eigen 和项目预期的路径不一致）</li><li>easywsclient 的源码路径</li><li>OpenVINO 的 cmake 路径</li></ol><p>编译命令：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cmake </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">S </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">B build </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">G </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;NMake Makefiles&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ^</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DCMAKE_TOOLCHAIN_FILE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">C:\\dev\\vcpkg\\scripts\\buildsystems\\vcpkg.cmake ^</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DGESTALT_EIGEN_INCLUDE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">C:\\dev\\vcpkg\\installed\\x64</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">windows\\include\\eigen3 ^</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DGESTALT_EXTRA_INCLUDE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">C:\\dev ^</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DGESTALT_EASYWS_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">C:\\dev\\easywsclient ^</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DOpenVINO_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">python_site_packages</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">openvino</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cmake</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cmake </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">build build </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">target gestalt</span></span></code></pre></div><p>中间遇到几个坑：</p><ul><li>ATL 头文件报错 → 改用 WRL（Windows Runtime C++ Template Library）</li><li>游戏 Qt 窗口崩溃 → 加 <code>--showui=0</code> 参数</li><li>哨兵属性等待超时 → 加了 10 秒重试机制</li></ul><h3 id="仿真测试" tabindex="-1">仿真测试 <a class="header-anchor" href="#仿真测试" aria-label="Permalink to &quot;仿真测试&quot;">​</a></h3><p>游戏启动后创建 RMUC2026 对局，停在 Prepare 阶段，然后运行桥程序：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\build\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">gestalt.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ws_port</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> configs\\gestalt_sentry_outpost.yaml </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">setup</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mode</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ekf </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">fire</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">timeout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">120</span></span></code></pre></div><p>最终结果：</p><table tabindex="0"><thead><tr><th>指标</th><th>值</th></tr></thead><tbody><tr><td>检测率</td><td>86.6%</td></tr><tr><td>命中率</td><td>54.0%</td></tr><tr><td>EKF 角速度估计</td><td>w=2.51 rad/s（实际 2.51）</td></tr><tr><td>前哨站 HP</td><td>1500 → 420</td></tr><tr><td>造成伤害</td><td>1080</td></tr><tr><td>子弹出膛</td><td>100 发</td></tr></tbody></table><p>前哨站在仿真里会以 ±144°/s 旋转，自瞄系统需要实时估计旋转角度并计算提前量。54% 的命中率比基线（49%）略高，说明系统工作正常。</p><h2 id="学到的东西" tabindex="-1">学到的东西 <a class="header-anchor" href="#学到的东西" aria-label="Permalink to &quot;学到的东西&quot;">​</a></h2><h3 id="项目架构" tabindex="-1">项目架构 <a class="header-anchor" href="#项目架构" aria-label="Permalink to &quot;项目架构&quot;">​</a></h3><p>这个项目的代码分层很清晰：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/gestalt.cpp          ← 主循环，串联所有模块</span></span>
<span class="line"><span>tasks/auto_aim/          ← 自瞄算法（检测、跟踪、解算、瞄准、开火）</span></span>
<span class="line"><span>io/gestalt/              ← 游戏 I/O（WebSocket、共享内存帧捕获）</span></span>
<span class="line"><span>tools/                   ← 工具库（EKF、数学、日志）</span></span>
<span class="line"><span>configs/                 ← YAML 配置文件</span></span></code></pre></div><p>数据流是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>游戏画面 → YOLO 检测装甲板 → 匹配装甲板 ID → EKF 跟踪目标状态 → 计算瞄准角度 → 开火决策 → WebSocket 发送命令</span></span></code></pre></div><h3 id="自瞄原理" tabindex="-1">自瞄原理 <a class="header-anchor" href="#自瞄原理" aria-label="Permalink to &quot;自瞄原理&quot;">​</a></h3><p>读了 readme 里的&quot;轨迹视角下的自瞄理论&quot;，核心思想是：</p><ul><li><strong>传统方法</strong>：检测到装甲板 → 算当前位置 → 瞄准当前位置（有延迟）</li><li><strong>轨迹规划</strong>：预测目标未来轨迹 → 计算子弹飞行时间 → 瞄准未来位置 → 同时考虑云台控制能力</li></ul><p>关键公式：<code>yaw_shoot(t) = yaw_target(t + t_fly)</code>，即射击角度要提前 <code>t_fly</code> 时间。</p><h3 id="bench-测试流程" tabindex="-1">bench 测试流程 <a class="header-anchor" href="#bench-测试流程" aria-label="Permalink to &quot;bench 测试流程&quot;">​</a></h3><p>仿真不是直接开打，而是有严格的 gate 机制：</p><ol><li>生成哨兵车辆（Respawn）</li><li>等待属性就绪（class、team、hp）</li><li>导航到指定位置（outpost-lob 点）</li><li>认领外部瞄准（ExtAimClaim）</li><li>布置相机参数（armLength:0 收回吊臂）</li><li>开始比赛（SetMatchStatus 1）</li><li>连续帧检测 + EKF 跟踪 + 自动开火</li><li>超时后释放控制权</li></ol><p>任何一步失败都会安全退出，不会卡死游戏。</p><h2 id="作为新人的感受" tabindex="-1">作为新人的感受 <a class="header-anchor" href="#作为新人的感受" aria-label="Permalink to &quot;作为新人的感受&quot;">​</a></h2><p>虽然今天大部分操作是 AI 完成的，但过程中被迫理解了很多概念：</p><ul><li>为什么需要 vcpkg 而不是直接下载 dll</li><li>CMake toolchain 文件是什么</li><li>WebSocket 在这个系统里扮演什么角色</li><li>EKF 为什么能估计旋转角速度</li><li>bench 测试的 gate 机制为什么这么复杂</li></ul><p>下一步应该自己从零复现一遍，把每个步骤的理解夯实。</p><h2 id="接下来" tabindex="-1">接下来 <a class="header-anchor" href="#接下来" aria-label="Permalink to &quot;接下来&quot;">​</a></h2><ul><li>[ ] 自己从零搭建编译环境（不用 AI 辅助）</li><li>[ ] 读 <code>src/gestalt.cpp</code> 主循环，理解状态机</li><li>[ ] 读 <code>tasks/auto_aim/target.cpp</code>，理解 EKF 跟踪</li><li>[ ] 改 <code>min_confidence</code> 参数，观察检测率变化</li><li>[ ] 读&quot;轨迹视角下的自瞄理论&quot;，理解轨迹规划器</li></ul><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p>仿真跑通了，但真正的学习从现在开始——自己动手复现一遍，比看 AI 做十遍都有用。</p>`,42)])])}const E=i(e,[["render",n]]);export{c as __pageData,E as default};
